#!/usr/bin/env node
// arthome-collect-agent-docs — puts arthome-core's rules INTO this package so it
// can ship them.
//
// The documents live in `architecture/`, which is outside every package, so
// nothing published carries them. This copies the ones a consuming repository
// has to read into `packages/tooling/docs/`, which `files` ships and
// `.gitignore` ignores: it is BUILD OUTPUT, regenerated by `build`, so the copy
// inside this repository cannot drift from the original the way a committed one
// would.
//
// The copy in the CONSUMER is committed, and that is a different decision made
// for a different reason — see `sync-agent-docs.mjs`.

import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const PACKAGE_ROOT = path.resolve(HERE, '..');
const REPO_ROOT = path.resolve(PACKAGE_ROOT, '..', '..');

// ⚠ WHAT A CONSUMING REPOSITORY MUST READ, and nothing else. The rest of
//   `architecture/` is reference and large, and a copy of it in five repositories is
//   the parallel table this project spent a week removing.
const WANTED = ['critical-rules.md', 'code-conventions.md'];

// ⚠ `available-surface.md` IS GENERATED HERE RATHER THAN COLLECTED: derived from
//   `REPOSITORY_MAP.md` on every build, it cannot be staler than the map `check:map`
//   already guards, where a committed copy would need a gate of its own.
function generateSurface() {
  execFileSync(process.execPath, [path.join(HERE, 'generate-agent-map.mjs')], {
    cwd: REPO_ROOT,
    stdio: 'inherit',
  });
}

function main() {
  const out = path.join(PACKAGE_ROOT, 'docs');
  fs.mkdirSync(out, { recursive: true });
  generateSurface();
  let n = 0;
  for (const name of WANTED) {
    const from = path.join(REPO_ROOT, 'architecture', name);
    if (!fs.existsSync(from)) {
      console.error(`arthome-collect-agent-docs: architecture/${name} not found.`);
      return 1;
    }
    fs.copyFileSync(from, path.join(out, name));
    n += 1;
  }
  console.log(
    `arthome-collect-agent-docs: ${n} collected + 1 generated into packages/tooling/docs/`,
  );
  return 0;
}

process.exit(main());
